<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
$user=Auth::requireLogin();
if (isset($_GET['logout'])) { Auth::logout(); redirect('/admin/login.php'); }
try {
 $pdo=Database::connection();
 $stats=[
 'bookings'=>$pdo->query('SELECT COUNT(*) FROM bookings')->fetchColumn(),
 'new_bookings'=>$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='new'")->fetchColumn(),
 'confirmed'=>$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='confirmed'")->fetchColumn(),
 'trips'=>$pdo->query('SELECT COUNT(*) FROM trips')->fetchColumn(),
 'companies'=>$pdo->query("SELECT COUNT(*) FROM companies WHERE status='active'")->fetchColumn(),
 'customers'=>$pdo->query('SELECT COUNT(*) FROM customers')->fetchColumn(),
 'umrah'=>$pdo->query('SELECT COUNT(*) FROM umrah_requests')->fetchColumn(),
 'services'=>$pdo->query('SELECT COUNT(*) FROM service_requests')->fetchColumn(),
 ];
 $latest=$pdo->query('SELECT b.reference_code,b.status,b.passengers_count,b.created_at,c.full_name FROM bookings b JOIN customers c ON c.id=b.customer_id ORDER BY b.id DESC LIMIT 8')->fetchAll();
} catch(Throwable $e) { $stats=[];$latest=[];$error=$config['debug']?$e->getMessage():'تعذر تحميل بيانات لوحة التحكم.'; }
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>لوحة التحكم | أصل المتصدر</title><link rel="stylesheet" href="/assets/css/app.css"><style>.admin-shell{display:grid;grid-template-columns:230px 1fr;min-height:100vh}.sidebar{background:#10263f;color:#dbe4ed;padding:25px 18px}.sidebar .brand b{color:#fff}.side-links{display:grid;gap:7px;margin-top:35px}.side-links a{padding:11px;border-radius:8px;font-size:13px}.side-links a:hover,.side-links a.active{background:#ffffff18;color:#fff}.admin-main{padding:30px;min-width:0;background:#f6f8fa}.admin-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.admin-top h1{margin:0;color:#10263f}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:20px}.stat small{color:#718092}.stat strong{display:block;font-size:30px;color:#10263f}.panel{background:white;border:1px solid #e5eaf0;border-radius:12px;padding:20px;margin-top:20px;overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:right;padding:12px;border-bottom:1px solid #edf0f3;font-size:13px}th{color:#718092;font-weight:500}.error{color:#a33}@media(max-width:760px){.admin-shell{grid-template-columns:1fr}.sidebar{padding:12px 16px}.side-links{display:flex;overflow:auto;margin-top:12px}.side-links a{white-space:nowrap}.admin-main{padding:18px}.stats{grid-template-columns:repeat(2,1fr)}.admin-top{align-items:flex-start;gap:12px;flex-direction:column}}</style></head><body><div class="admin-shell"><aside class="sidebar"><a class="brand" href="/"><span class="brand-mark">م</span><span><b>أصل المتصدر</b><small>الإدارة المركزية</small></span></a><nav class="side-links"><a class="active" href="/admin/index.php">نظرة عامة</a><a href="/admin/trips.php">الرحلات</a><a href="/admin/bookings.php">الحجوزات</a><a href="/admin/companies.php">شركات 